    '{count} of {total, plural, =1{# link} other{# links}}' => '{count} van {total, plural, =1{# link} other{# links}}',
    '{n, plural, =1{# page} other{# pages}}' => '{n, plural, =1{# pagina} other{# pagina\'s}}',
